SELECT *
FROM ip_adjust_step_fund
WHERE adjust_log_id = #{adjustLogId}
  AND adjust_batch_no = #{adjustBatchNo}
  AND flow_node_id = #{flowNodeId}
  AND handler_id = #{handlerId}
  AND step_status = 'pending'
ORDER BY id ASC
LIMIT 1

SELECT COUNT(1)
FROM ip_adjust_step_fund
WHERE adjust_log_id = #{adjustLogId}
  AND adjust_batch_no = #{adjustBatchNo}
  AND flow_node_id = #{flowNodeId}
  AND step_status = 'pending'

mapper.update:
UPDATE ip_adjust_step_fund
SET step_status = #{stepStatus}
   ,process_action = #{processAction}
   ,process_comment = #{processComment}
   ,process_time = NOW()
   ,updt_time = NOW()
WHERE id = #{id}
  AND step_status = 'pending'

UPDATE ip_adjust_step_fund
SET step_status = #{stepStatus}
   ,process_action = 'skipped'
   ,process_time = NOW()
   ,updt_time = NOW()
WHERE adjust_log_id = #{adjustLogId}
  AND adjust_batch_no = #{adjustBatchNo}
  AND flow_node_id = #{flowNodeId}
  AND step_status = 'pending'
  AND id != #{id}

mapper.select:
SELECT COUNT(1) > 0
FROM ip_pool_open_day
WHERE pool_id = #{poolId}
  AND begin_date <= #{today}
  AND end_date >= #{today}
  AND is_deleted = 0

SELECT COUNT(1) > 0
FROM ip_adjust_log_fund al
INNER JOIN ip_adjust_step_fund step ON step.adjust_batch_no = al.adjust_batch_no
WHERE al.fund_code = #{fundCode}
  AND al.target_pool_id = #{targetPoolId}
  AND al.audit_status IN ('00', '11')
  AND al.is_deleted = 0
  AND step.step_status = 'pending'

    AND al.adjust_batch_no != #{excludedBatchNo}

SELECT COUNT(1) > 0
FROM ip_adjust_log_fund
WHERE fund_code = #{fundCode}
  AND target_pool_id = #{targetPoolId}
  AND adjust_mode = #{adjustMode}
  AND adjuster_id = #{adjusterId}
  AND submit_time >= DATE_SUB(NOW(), INTERVAL 30 SECOND)
  AND is_deleted = 0
